import {createFacility} from './scene.js';
import {createEquipment} from './equipment.js';
const main=document.querySelector('main');
const arrow='↗';
const icons={
room:'<path d="M3 10 12 5l9 5v10l-9 5-9-5V10Z M3 10l9 5 9-5 M12 15v10 M7 8l9 5v8"/>',
air:'<path d="M3 8h13a3 3 0 1 0-3-3 M3 13h20a3 3 0 1 1-3 3 M3 18h8a3 3 0 1 1-3 3"/>',
mep:'<path d="M5 24V9h5V3h8v6h5v15 M10 9h8 M10 13h2m3 0h3 M10 17h2m3 0h3 M12 24v-4h4v4"/>',
test:'<path d="M8 5H5v20h18V5h-3 M10 3h8v5h-8V3Z M9 15l3 3 7-7 M9 22h10"/>',
facility:'<path d="m18 3 4 4-4 4-4-4 4-4Z M4 22l10-10 M4 22l3 3 10-10 M5 4l6 6 M3 3l2 5 3-3-5-2Z"/>',
retro:'<path d="M23 12a10 10 0 0 0-17-7L2 9 M2 3v6h6 M5 16a10 10 0 0 0 17 6l4-4 M26 24v-6h-6 M16 9l-5 7h5l-2 6"/>'};
const icon=name=>`<svg viewBox="0 0 28 28" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.room}</svg>`;
const services=[
  ['cleanroomequipment.html','Clean room solutions','Modular environments, engineered around the precision your process demands.','room'],
  ['hvacservices.html','HVAC & air systems','Complete environmental control, from system design to energy-efficient retrofits.','air'],
  ['mepcontractors.html','MEP contracting','Mechanical, electrical and plumbing systems. One integrated engineering partner.','mep'],
  ['validations.html','Testing & validation','Understand your environment with clean room testing and detailed documentation.','test'],
  ['facilityengservices.html','Facility maintenance','Keep critical equipment and utilities operating with dedicated engineering support.','facility'],
  ['service.html#retrofit','Energy-efficient retrofits','Reimagine existing HVAC systems with direct-drive and EC fan technology.','retro']
];
const products=[
  ['cleanroompanels.html','Clean room panels','Clean rooms','home-crp.png','Modular panels with configurable finishes and infill materials.'],
  ['galvanizedironCR.html','GI clean room partitions','Clean rooms','about-us-img.png','Galvanized iron partitions for controlled environments.'],
  ['cleanroomdoors.html','Clean room doors','Clean rooms','crd.png','Doors designed for modular clean room applications.'],
  ['horizontallaminarflow.html','Horizontal laminar flow','Airflow & containment','hlaf.png','Horizontal unidirectional airflow for product protection.'],
  ['verticallaminarflow.html','Vertical laminar flow','Airflow & containment','vlaf.png','HEPA-filtered vertical airflow for critical processes.'],
  ['reverselaminarflow.html','Reverse laminar flow','Airflow & containment','rlaf.png','Controlled containment for material handling.'],
  ['staticpassbox.html','Static pass box','Transfer systems','home-passbox.png','Transfer materials between controlled environments.'],
  ['dynamicpassbox.html','Dynamic pass box','Transfer systems','home-passbox.png','Filtered airflow for clean room material transfer.'],
  ['airshower.html','Air shower','Transfer systems','home-airshower.png','Personnel decontamination before clean room entry.'],
  ['biosafetycabinet.html','Biosafety cabinet','Airflow & containment','bsc.png','Cabinets for laboratory containment applications.'],
  ['labfurniture.html','Laboratory furniture','Furniture','labfurniture.png','Practical furniture for laboratory workflows.'],
  ['airhandlingunit.html','Air handling unit','HVAC systems','home-ahu.png','Air filtration and conditioning for your facility.'],
  ['hvacsystems.html','HVAC systems','HVAC systems','hvac-system.png','Integrated heating, ventilation and air conditioning.'],
  ['ssfurnitures.html','Stainless steel furniture','Furniture','ssfurnitures.png','Stainless steel equipment for clean room applications.']
];
let content={};
try {const response=await fetch('content.json');if(!response.ok)throw Error();content=await response.json();}catch{main.innerHTML='<section class="section wrap"><h1>Unable to load this page</h1><p>Please refresh, or <a href="mailto:info@aemsinfra.com">contact AEMS</a>.</p></section>';}
const filename=decodeURIComponent(location.pathname.split('/').filter(Boolean).pop()||'index.html');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(url,label,style='')=>`<a class="button ${style}" href="${url}">${label}<span>${arrow}</span></a>`;
const cta=()=>`<section class="cta-section"><div class="wrap cta-box"><div><h2>Let’s engineer what’s next.</h2><p>A new facility. A smarter system. A better environment. Start with a conversation.</p></div>${button('contact.html','Discuss your project','dark')}</div></section>`;
function serviceCards(){return services.map(([url,name,description,ico],i)=>`<a href="${url}" class="service-card ${i===5?'accent':''}"><div class="service-icon">${icon(ico)}</div><span class="arrow">↗</span><h3>${name}</h3><p>${description}</p><span class="num">0${i+1}</span></a>`).join('');}
function productImage(p){const images=content[p[0]]?.images||[];const featured=['home-crp.png','home-passbox.png','home-airshower.png','home-ahu.png','hvac-system.png'];return featured.includes(p[3])?'assets/img/'+p[3]:(images[0]||'assets/img/'+p[3]);}
function productCard(p){return `<a href="${p[0]}" class="product-card"><div class="product-image"><span class="product-badge">Explore in 3D <span>◇</span></span><img src="${productImage(p)}" alt="${esc(p[1])}" loading="lazy"><span class="product-open" aria-hidden="true">↗</span></div><div class="product-info"><small>${p[2]}</small><h3>${p[1]}</h3><p>${p[4]}</p><span class="product-bottom">View product <span>↗</span></span></div></a>`;}
function pageHero(title,description,section='AEMS Infra'){return `<section class="page-hero"><div class="wrap"><div class="breadcrumbs"><a href="index.html">Home</a><span>/</span><span>${section}</span></div><div class="eyebrow">${section}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div></section>`;}
function home(){main.innerHTML=`
<section class="hero hero-material"><div class="hero-grain"></div><div class="wrap hero-grid"><div class="hero-copy reveal"><div class="hero-pill"><span class="live-dot"></span> ENGINEERED FOR WHAT’S NEXT</div><h1>Better spaces.<br>Smarter systems.<br><em>Built together.</em></h1><p>Clean room technology. Intelligent HVAC. Integrated MEP.<br>We connect every detail to bring your vision to life.</p><div class="actions">${button('service.html','Discover our solutions')}<a href="products.html" class="text-link">Explore products <span>↗</span></a></div><div class="hero-proof"><div class="proof-icon">${icon('room')}</div><div><strong>One partner. Every possibility.</strong><span>From first concept to final commissioning.</span></div></div></div>
<div class="scene-shell"><div class="scene-heading"><span class="live-dot"></span> A CONNECTED ENVIRONMENT <span class="model-index">01 / 03</span></div><div class="scene-canvas" role="img" tabindex="0"></div><button class="scene-label label-a" data-focus="hvac"><span class="hotspot-icon">+</span><span><small>ENVIRONMENTAL CONTROL</small>Precision air handling</span></button><button class="scene-label label-b" data-focus="room"><span class="hotspot-icon">+</span><span><small>MODULAR BY DESIGN</small>Clean room technology</span></button><button class="scene-label label-c" data-focus="mep"><span class="hotspot-icon">+</span><span><small>ONE INTEGRATED SYSTEM</small>MEP engineering</span></button><div class="scene-toolbar" role="group" aria-label="Explore the 3D facility"><button data-scene="all" aria-pressed="true">◇ <span>Facility</span></button><button data-scene="air" aria-pressed="false">≋ <span>Airflow</span></button><button data-scene="exploded" aria-pressed="false">▱ <span>Exploded</span></button></div><div class="scene-caption">CONCEPTUAL 3D ENVIRONMENT<span>Drag to rotate · Arrow keys to explore</span></div><div class="scene-status"><button data-scene="motion" class="motion-button" aria-pressed="${matchMedia('(prefers-reduced-motion: reduce)').matches}">${matchMedia('(prefers-reduced-motion: reduce)').matches?'Play motion':'Pause motion'}</button><button data-scene="reset" class="motion-button">Reset view ↺</button></div></div></div>
<div class="hero-bottom wrap"><div class="hero-bottom-label">PURPOSE-BUILT FOR<br><strong>THE INDUSTRIES THAT MATTER.</strong></div><div class="industries"><span>Pharmaceutical</span><span>Healthcare</span><span>Biotechnology</span><span>Food processing</span></div><a href="#solutions" class="scroll-cue" aria-label="Explore our solutions"><span>↓</span></a></div></section>
<section class="trust-section"><div class="wrap trust-layout"><p>Our clients.<br><strong>Our commitment.</strong></p><div class="logo-row">${(content['clients.html']?.images||[]).slice(0,6).map((url,i)=>`<a href="clients.html"><img src="${url}" alt="AEMS client ${i+1}" loading="lazy"></a>`).join('')}</div><a href="clients.html" class="round-link" aria-label="View all clients">↗</a></div></section>
<section class="section" id="solutions"><div class="wrap"><div class="section-head"><div><div class="eyebrow">01 / Connected expertise</div><h2>Big-picture thinking.<br><span class="muted-title">Every detail considered.</span></h2></div><div><p>One integrated partner for the environments where quality, safety and performance matter most.</p><a class="text-link" href="service.html">Explore all solutions <span>↗</span></a></div></div><div class="service-grid material-bento">${serviceCards()}</div></div></section>
<section class="section approach-section"><div class="wrap about-strip"><div class="about-image"><img src="assets/img/about-us-img.png" alt="AEMS clean room interior" loading="lazy"><div class="image-overlay"><span>◇</span><div>Every detail has a purpose.<small>Controlled environments. Considered design.</small></div></div><span class="image-tag">PRECISION, BUILT IN.</span></div><div><div class="eyebrow">02 / The AEMS approach</div><h2>Engineering is complex.<br><span class="muted-title">Working with us<br>shouldn’t be.</span></h2><p>Aditya Electro Mechanical Solutions brings clean room technology, environmental control and MEP engineering together—from the first conversation to a fully commissioned facility.</p><div class="approach-points"><div><span>01</span><p><strong>Designed around your process</strong>Customised solutions for your environment.</p></div><div><span>02</span><p><strong>Connected from the start</strong>Equipment, systems and people in sync.</p></div><div><span>03</span><p><strong>Care that continues</strong>Validation, maintenance and ongoing support.</p></div></div><a class="text-link" href="about.html">Meet your engineering partner <span>↗</span></a></div></div></section>
<section class="section products-section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">03 / Product collection</div><h2>Purpose in every product.<br><span class="muted-title">Precision in every detail.</span></h2></div>${button('products.html','Explore the collection','light')}</div><div class="product-grid">${[products[0],products[11],products[6],products[8]].map(productCard).join('')}</div><div class="collection-note"><span>◇</span> A closer look changes everything. Explore conceptual equipment models in 3D.</div></div></section>
<section class="section process"><div class="wrap"><div class="section-head"><div><div class="eyebrow">04 / Your vision. Our process.</div><h2>From a possibility.<br><span>To a place that performs.</span></h2></div><p>A considered, connected approach to every stage of your project.</p></div><div class="process-grid">${[['Understand','Your process. Your ambitions. Your requirements. We start by listening.','room'],['Engineer','Architecture, equipment and building services. Designed to work as one.','mep'],['Bring to life','Supply, installation and system integration. Coordinated down to the detail.','facility'],['Make it perform','Testing, validation and documentation. Ready for what comes next.','test']].map(([title,p,ico],i)=>`<div class="process-step"><div class="process-top"><span>0${i+1}</span>${icon(ico)}</div><h3>${title}</h3><p>${p}</p></div>`).join('')}</div><div class="process-foot"><span>Safety. Improvement. Morals.</span><a href="service.html">Discover the AEMS difference ↗</a></div></div></section>
<section class="section affiliations-home"><div class="wrap"><div><div class="eyebrow">Connected to our industry</div><h2>Better, together.</h2></div><div class="affiliation-logos">${(content['affiliations.html']?.images||[]).map((url,i)=>`<a href="affiliations.html"><img src="${url}" alt="AEMS affiliation ${i+1}" loading="lazy"></a>`).join('')}</div></div></section>${cta()}`;
createFacility(document.querySelector('.scene-canvas'));}
function catalogue(){main.innerHTML=pageHero('Equipment that brings<br>your environment to life.','Explore the complete AEMS clean room and HVAC equipment range. Find your product, review its specifications and discuss your requirements.','Product catalogue')+`<section class="section"><div class="wrap"><div class="catalogue-tools"><div class="filters" role="group" aria-label="Product categories">${['All products',...new Set(products.map(p=>p[2]))].map((c,i)=>`<button class="filter" data-filter="${c}" aria-pressed="${i===0}">${c}</button>`).join('')}</div><label class="search"><input type="search" aria-label="Search products" placeholder="Search the catalogue"><span aria-hidden="true">⌕</span></label></div><p class="results-count" aria-live="polite"></p><div class="product-grid" id="catalogue"></div></div></section>${cta()}`;
let category='All products',query='';const draw=()=>{const shown=products.filter(p=>(category==='All products'||p[2]===category)&&`${p[1]} ${p[2]} ${p[4]}`.toLowerCase().includes(query));document.querySelector('#catalogue').innerHTML=shown.length?shown.map(productCard).join(''):'<div class="empty"><h3>No products found</h3><p>Try another search or select All products.</p></div>';document.querySelector('.results-count').textContent=`${shown.length} of ${products.length} products`;};draw();document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;document.querySelectorAll('.filter').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===category)));draw();}));document.querySelector('.search input').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();draw();});}
function servicesPage(){main.innerHTML=pageHero('Every system.<br>One engineering partner.','Discover AEMS services across clean room design, HVAC, MEP, validation, facility maintenance and energy-efficient retrofits.','Our solutions')+`<section class="section"><div class="wrap"><div class="service-grid">${serviceCards()}</div></div></section><section class="section" style="padding-top:0"><div class="wrap detail-grid"><aside class="detail-side"><div class="eyebrow">Engineering services</div><h3>Explore the details.</h3><div class="side-links"><h3>Jump to a service</h3></div></aside><article class="technical">${content['service.html']?.content||''}</article></div></section>${cta()}`;
const heads=[...document.querySelectorAll('.technical>h3')];heads.forEach((h,i)=>{h.id=h.textContent.toLowerCase().includes('retrofit')?'retrofit':`service-${i}`;document.querySelector('.side-links').insertAdjacentHTML('beforeend',`<a href="#${h.id}">${esc(h.textContent)}</a>`);});}
function about(){main.innerHTML=pageHero('Engineering with purpose.','Integrated engineering solutions, a qualified team and a shared commitment to quality in every environment.','About AEMS')+`<section class="section"><div class="wrap about-strip"><div class="technical">${content['about.html']?.content||''}</div><div class="about-image"><img src="assets/img/about-us-img.png" alt="AEMS clean room installation"><div class="image-overlay">Safety. Improvement. Morals.</div></div></div><div class="wrap mission-grid"><div><div class="eyebrow">Our vision</div><h3>Quality, first time. Every time.</h3><p>We are committed to providing our customers the highest quality of service and ensuring their total satisfaction.</p></div><div><div class="eyebrow">Our mission</div><h3>Invest in people. Improve continuously.</h3><p>Develop a diverse workforce and invest in training, development and technology to provide the best possible service to our customers.</p></div></div></section>${cta()}`;}
function gallery(type){const isClients=type==='clients.html';const data=content[type];main.innerHTML=pageHero(isClients?'Relationships built<br>through engineering.':'Connected to our industry.',isClients?'The organisations featured on the AEMS client portfolio.':'The affiliations featured by AEMS Infra.',isClients?'Our clients':'Our affiliations')+`<section class="section"><div class="wrap"><div class="logo-gallery">${(data?.images||[]).map((url,i)=>`<div class="logo-tile"><img src="${url}" alt="${isClients?'Client':'Affiliation'} logo ${i+1} from the AEMS portfolio" loading="lazy"></div>`).join('')}</div></div></section>${cta()}`;}
function contact(){const selected=new URLSearchParams(location.search).get('product')||'';main.innerHTML=pageHero('Your next project<br>starts with a conversation.','Tell us what you’re building. Our engineering team can help with your clean room, HVAC, MEP and equipment requirements.','Contact AEMS')+`<section class="section"><div class="wrap contact-grid"><div class="contact-info"><div class="eyebrow">Let’s connect</div><h2>Built around<br>your requirements.</h2><div class="contact-block"><small>Call our team</small><a href="tel:+919000230419">+91 90002 30419 ↗</a><a href="tel:04048586464">040-48586464 ↗</a></div><div class="contact-block"><small>Email us</small><a href="mailto:info@aemsinfra.com">info@aemsinfra.com ↗</a></div><div class="contact-block"><small>Visit our office</small><p>#8-2-611/3, Flat No. 104, First Floor,<br>Farhat Afza Building, beside Shankarlal & Sons,<br>Road No. 10, Banjara Hills,<br>Hyderabad 500034, Telangana, India.</p></div><div class="map-card"><a href="https://www.google.com/maps/search/?api=1&query=Farhat+Afza+Building+Road+10+Banjara+Hills+Hyderabad" target="_blank" rel="noopener">Find our office on Google Maps ↗</a></div></div><form class="contact-form"><h3>Tell us about your project.</h3><p>Share a few details to prepare an enquiry for our engineering team.</p><div class="form-grid"><div class="field"><label for="name">Your name *</label><input id="name" name="name" autocomplete="name" required placeholder="Full name"></div><div class="field"><label for="company">Company</label><input id="company" name="company" autocomplete="organization" placeholder="Organisation name"></div><div class="field"><label for="email">Work email *</label><input id="email" name="email" type="email" autocomplete="email" required placeholder="you@company.com"></div><div class="field"><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="+91"></div><div class="field full"><label for="interest">I’m interested in</label><select id="interest" name="interest">${['General enquiry',...services.slice(0,5).map(s=>s[1]),...products.map(p=>p[1])].map(s=>`<option ${s===selected?'selected':''}>${s}</option>`).join('')}</select></div><div class="field full"><label for="message">Project requirements *</label><textarea id="message" name="message" required placeholder="Tell us about your facility, equipment or project requirements…"></textarea></div></div><button type="submit" class="button">Prepare email enquiry <span>↗</span></button><p class="form-note">Opens your email app with these details. Review and send your enquiry there.</p><div class="form-status" role="status"></div></form></div></section>`;
document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const body=`Name: ${d.get('name')}\nCompany: ${d.get('company')}\nEmail: ${d.get('email')}\nPhone: ${d.get('phone')}\nInterest: ${d.get('interest')}\n\nProject requirements:\n${d.get('message')}`;const mailto=`mailto:info@aemsinfra.com?subject=${encodeURIComponent('Project enquiry — '+d.get('interest'))}&body=${encodeURIComponent(body)}`;document.querySelector('.form-status').innerHTML=`Your enquiry is ready. <a class="text-link" href="${mailto}">Open your email app ↗</a> or copy the enquiry below. <button type="button" class="filter" id="copy-enquiry">Copy enquiry</button>`;document.querySelector('#copy-enquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(body);document.querySelector('#copy-enquiry').textContent='Copied ✓';}catch{document.querySelector('.form-status').insertAdjacentHTML('beforeend',`<textarea readonly aria-label="Prepared enquiry" style="width:100%;min-height:200px">${esc(body)}</textarea>`);}});});}
function detail(name){const data=content[name];if(!data){notFound();return;}const p=products.find(p=>p[0]===name);const s=services.find(s=>s[0]===name);const title=p?.[1]||s?.[1]||data.title;const description=p?.[4]||s?.[2]||data.description;const category=p?'Product catalogue':'Engineering solutions';const image=p?productImage(p):data.images[0];const list=p?products:services.slice(0,5);
main.innerHTML=pageHero(esc(title),esc(description),category)+`<section class="section"><div class="wrap detail-grid"><aside class="detail-side">${image?`<div class="detail-photo"><img src="${image}" alt="${esc(title)}"></div>`:''}${button('contact.html?product='+encodeURIComponent(title),'Enquire about this '+(p?'product':'service'))}<a class="text-link" href="${p?'products.html':'service.html'}">${p?'All products':'All solutions'} <span>↗</span></a><div class="side-links"><h3>${p?'Product catalogue':'Our solutions'}</h3>${list.map(item=>`<a href="${item[0]}" class="${item[0]===name?'current':''}">${item[1]}</a>`).join('')}</div></aside><article class="technical">${data.content}<div class="technical-gallery">${data.images.filter(url=>url!==image).map(url=>`<img src="${url}" alt="${esc(title)} — additional product illustration" loading="lazy">`).join('')}</div><div class="detail-actions">${button('contact.html?product='+encodeURIComponent(title),'Discuss your requirements')}<button class="button light" id="print-specs">Print this page ↓</button></div></article></div></section>${cta()}`;document.querySelector('#print-specs').addEventListener('click',()=>window.print());}
function notFound(){main.innerHTML=pageHero('Let’s get you<br>to the right place.','This page could not be found. Explore our complete range of solutions and products.','Page not found')+`<section class="section wrap"><div class="actions">${button('index.html','Return home')}${button('products.html','Browse products','light')}</div></section>`;}
if(Object.keys(content).length){if(filename==='index.html')home();else if(filename==='products.html')catalogue();else if(filename==='service.html')servicesPage();else if(filename==='about.html')about();else if(['clients.html','affiliations.html'].includes(filename))gallery(filename);else if(filename==='contact.html')contact();else detail(filename);}
const selectedProduct=products.find(p=>p[0]===filename);
if(selectedProduct&&Object.keys(content).length){
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  document.querySelector('.page-hero').insertAdjacentHTML('afterend',`<section class="equipment-showcase"><div class="wrap equipment-layout"><div class="equipment-stage"><div class="equipment-tools" role="group" aria-label="Product viewer"><button data-equipment="model" aria-pressed="true">◇ 3D model</button><button data-equipment="photo" aria-pressed="false">Product photo</button><button data-equipment="motion" aria-pressed="${reduced}">${reduced?'Play motion':'Pause motion'}</button></div><div class="equipment-canvas" role="img" aria-label="Conceptual 3D model of ${esc(selectedProduct[1])}. Drag to rotate, or use left and right arrow keys." tabindex="0"></div><span class="equipment-hint">Drag to explore · Arrow keys to rotate</span><button class="equipment-reset" data-equipment="reset" aria-label="Reset product view">↺</button></div><div class="equipment-copy"><div class="eyebrow">A new perspective</div><h2>Get closer to<br>every detail.</h2><p>${selectedProduct[4]} Explore the concept in 3D, then review the original product photography and full technical information.</p><a class="text-link" href="#technical-details">View technical details <span>↓</span></a><div class="equipment-note">Concept model for illustration. Refer to the original specifications and confirm construction details with the AEMS engineering team.</div></div></div></section>`);
  document.querySelector('.technical').id='technical-details';createEquipment(document.querySelector('.equipment-canvas'),filename,productImage(selectedProduct));
}
document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelector('.mobile-toggle').addEventListener('click',e=>{const open=document.querySelector('#navigation').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.setAttribute('aria-label',open?'Close navigation':'Open navigation');e.currentTarget.textContent=open?'×':'☰';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('details[open]').forEach(d=>d.open=false);document.querySelector('#navigation').classList.remove('open');document.querySelector('.mobile-toggle').setAttribute('aria-expanded','false');}});
document.addEventListener('click',e=>document.querySelectorAll('details[open]').forEach(d=>{if(!d.contains(e.target))d.open=false;}));
document.querySelectorAll('.technical table').forEach(table=>{const wrap=document.createElement('div');wrap.className='table-scroll';table.before(wrap);wrap.append(table);});
document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{if(!img.dataset.fallback){img.dataset.fallback='1';img.src='assets/img/about-us-img.png';}}));
if(filename!=='index.html'){const title=document.querySelector('h1')?.textContent.replace(/\s+/g,' ').trim();if(title)document.title=`${title} | AEMS Infra`;}
if(location.hash){requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());}
document.querySelectorAll('nav>a').forEach(a=>{if(a.getAttribute('href')===filename)a.setAttribute('aria-current','page');});
const backTop=document.createElement('button');backTop.className='back-top';backTop.type='button';backTop.textContent='↑';backTop.setAttribute('aria-label','Back to top');document.body.append(backTop);backTop.addEventListener('click',()=>scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
const updateScroll=()=>{document.querySelector('.header').classList.toggle('scrolled',scrollY>25);backTop.classList.toggle('visible',scrollY>750);};addEventListener('scroll',updateScroll,{passive:true});updateScroll();
document.addEventListener('pointerdown',e=>{const target=e.target.closest('.button,.nav-cta,.filter,.scene-toolbar button,.equipment-tools button');if(!target||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const rect=target.getBoundingClientRect(),size=Math.max(rect.width,rect.height);const ripple=document.createElement('span');ripple.className='ripple';ripple.style.width=ripple.style.height=`${size}px`;ripple.style.left=`${e.clientX-rect.left-size/2}px`;ripple.style.top=`${e.clientY-rect.top-size/2}px`;target.append(ripple);setTimeout(()=>ripple.remove(),750);});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const reveal=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('md-enter');reveal.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('.section-head,.about-strip,.process-step').forEach(el=>reveal.observe(el));}
